extra='''.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.control-grid label{margin:8px 0}.control-grid input:not([type=checkbox]),.control-grid select{width:100%;font:inherit;font-size:21px;line-height:1.5;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink)}.control-grid input[type=checkbox]{width:22px;height:22px;vertical-align:middle}.metric-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:24px 0}.metric{padding:20px;background:var(--soft);border:1px solid var(--line);border-radius:18px}.metric strong{display:block;font-size:30px}.type-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.type-grid p{margin:0;overflow-wrap:anywhere}.type-grid strong{font-size:28px}.trace-panel{margin:28px 0}#events{max-height:550px}#events .partial{display:none}#events.show-partial .partial{display:block}.diff-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:28px 0}.diff-grid pre{max-height:500px}.check-badge{display:inline-block;padding:10px 16px;background:var(--soft);border-radius:12px;font-weight:800;font-size:22px}#answer{max-height:380px;overflow:auto}.loop-label{font-size:24px;font-weight:800;background:var(--soft);border-radius:14px;padding:16px;margin:20px 0}#status{overflow-wrap:anywhere}#result-text{white-space:pre-wrap;overflow-wrap:anywhere}.summary-list p{overflow-wrap:anywhere}@media(max-width:850px){.control-grid,.metric-grid,.diff-grid,.type-grid{grid-template-columns:1fr}}'''
(PUBLIC/'style.css').write_text((PUBLIC/'style.css').read_text(encoding='utf-8')+extra,encoding='utf-8')
agent=(APP/'src/agent.ts').read_text(encoding='utf-8');sample=(APP/'src/sample.ts').read_text(encoding='utf-8');fixture=(APP/'fixtures/auth.ts').read_text(encoding='utf-8')
def part(source,start,end):return source[source.index(start):source.index(end,source.index(start))].strip()
learn=[('Follow the five-stage loop','Prompt → model response → tool execution → feedback → repeat or final result. The SDK owns orchestration; your iterator observes it.'),('Separate messages, blocks and turns','Several assistant messages may share one response ID. Partial stream events are not turns. Read the SDK num_turns separately from observed response groups.'),('Correlate requests and feedback','assistant tool_use.id links to user tool_result.tool_use_id. The interface shows these identifiers and safe descriptions instead of raw credentials or hidden reasoning.'),('Observe real execution and approvals','Read/Edit/Glob/Bash availability is separate from allowedTools pre-approval and disallowedTools. Hooks observe and guard real calls; they do not fabricate a fixed four-turn script.'),('Experiment with limits and effort','Compare a normal repair with maxTurns: 1, change the SDK budget, and try supported low/high effort. A stopped run stays a stopped run.'),('Handle the actual final outcome','Inspect subtype, stop_reason, num_turns, usage, estimated cost and session ID. Continue iteration to completion and preserve an observed error result if the runtime then closes.')]
clone='git clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson04-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson04-app\nnpm ci'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3104'
shell='$env:ANTHROPIC_API_KEY = "your_api_key"\nnpm run sample -- repair low\nnpm run sample -- limit low\nnpm run sample -- inspect high'
walk=[('01','Create a reproducible failing task','fixtures/auth.ts','Three cases fail: a missing user crashes, an inactive administrator is allowed, and an active viewer is allowed. Only an active administrator should pass. The test file remains unchanged.',fixture,'typescript'),('02','Configure the scenario and limits','src/agent.ts','Inputs are validated before starting the runtime. The limit preset forces maxTurns to 1. Effort and partial-message settings are actual SDK options, not a simulated dashboard.',part(agent,'export function validateConfig','export async function verifyFile'),'typescript'),('03','Set availability, approval and settings','src/agent.ts','The repair scenario enables Read/Edit/Glob/Bash, with only exactly npm test allowed by the host guard. Read-only inspection removes editing and Bash. Project settings are opt-in and the fixture includes a classroom CLAUDE.md.',part(agent,'export function lessonOptions','export class TraceProjector'),'typescript'),('04','Group assistant response IDs','src/agent.ts','Every observed message increments its type count. Assistant message.message.id groups blocks from the same response. This grouped count is labelled separately from the final SDK num_turns.',part(agent,'    if (message.type === "assistant")','    if (message.type === "user")'),'typescript'),('05','Match tool results to their requests','src/agent.ts','A tool request records its block ID and response group. A later user tool_result carries tool_use_id, so feedback can be linked without assuming every user message is a human prompt.',part(agent,'    if (message.type === "user")','    if (message.type === "stream_event")'),'typescript'),('06','Preserve result metadata on every subtype','src/agent.ts','Only success with is_error false is success. Other subtypes keep their identity while cost, usage, turn count, stop reason and session ID remain available. Stream events update counts without inventing more turns.',part(agent,'    if (message.type === "stream_event")','    events.unshift'),'typescript'),('07','Iterate to completion, then check the file','src/agent.ts','The host does not break at the result. If the runtime throws after yielding a result, the observed subtype is preserved. A failure before any result remains an error. Independent host checks examine the actual resulting auth.ts.',part(agent,'export async function runAgent', '\n  } finally')+'\n  } finally {\n    conversation.close();\n    const source = await readFile(TARGET, "utf8");\n    emit({ type: "workspace", stage: "after", source, checks: await verifyFile(), changed: source !== before });\n  }\n}','typescript')]
controls='''<div class="control-grid"><label>Scenario<select id="scenario"><option value="repair">Repair auth.ts</option><option value="limit">Hit maxTurns: 1</option><option value="inspect">Read-only inspection</option></select></label><label>maxTurns<input id="max-turns" type="number" min="1" max="12" value="10"></label><label>SDK budget USD<input id="budget" type="number" min="0.0001" max="1" step="0.0001" value="0.50"></label><label>Effort<select id="effort"><option value="low">low</option><option value="high">high</option></select></label><label><input type="checkbox" id="partial" checked> Request partial SDK messages</label><label><input type="checkbox" id="project"> Load project settings</label></div>'''
types=''.join(f'<article class="metric"><p>{t}</p><strong id="count-{t}">0</strong></article>' for t in ['system','assistant','user','stream_event','result'])
body='<div class="flow"><div><b>01 · Prompt</b><p>Start one query</p></div><span>→</span><div><b>02 · Tools ↔ feedback</b><p>The SDK repeats the loop</p></div><span>→</span><div><b>03 · Result</b><p>Inspect the subtype and evidence</p></div></div><section class="workspace"><article class="panel"><p class="eyebrow">CONTROL THE REAL LOOP</p><h2>Choose an experiment</h2><p id="configuration" class="meta">Checking local configuration…</p><form id="form"><label for="prompt">Prompt</label><textarea id="prompt" required maxlength="2000"></textarea>'+controls+'<p class="meta">Model: <strong id="model">—</strong></p><button class="primary" id="run" disabled>Run agent loop →</button></form><p class="meta">Each run restores the demo files. The host permits reads, auth.ts edits, and exactly npm test. The read-only preset cannot edit or run commands.</p></article><article class="panel summary-list"><p class="eyebrow">FINAL SDK OUTCOME</p><h2 id="status">Ready</h2><div class="stats"><div class="stat"><span>SDK num_turns</span><strong id="turns">0</strong></div><div class="stat"><span>Estimated cost</span><strong id="cost">—</strong></div></div><p>stop_reason: <strong id="stop">—</strong></p><p>Usage: <span id="usage">—</span></p><p class="meta">Session ID: <span id="session">—</span></p><h3>Assistant text</h3><div id="answer"></div><h3 style="margin-top:24px">Result text / errors</h3><p id="result-text"></p><p id="notice" class="note"></p></article></section><section class="panel trace-panel" id="trace"><h2>Observe messages, not an invented loop</h2><div class="metric-grid"><article class="metric">SDK messages<strong id="messages">0</strong></article><article class="metric">Assistant responses · grouped by ID<strong id="responses">0</strong></article><article class="metric">Distinct tool requests<strong id="requests">0</strong></article></div><div class="type-grid">'+types+'</div><p>These are different measurements. Partial deltas and multiple content blocks must not be counted as extra turns.</p><label><input id="show-partial" type="checkbox"> Show partial events in the trace</label><ol id="events"></ol><button id="download" type="button">Download observed events JSON</button><p class="meta">Tool requests/results share an ID. Hook durations are host observations, not model billing measurements. The actual tool order and any overlap are model/runtime decisions.</p></section><section class="diff-grid"><article class="panel"><h2>Before · auth.ts</h2><p class="check-badge" id="before-checks">Checking baseline…</p><pre><code class="language-typescript" id="before"></code></pre></article><article class="panel"><h2>After · actual file</h2><p class="check-badge" id="after-checks">Not checked</p><pre><code class="language-typescript" id="after">The resulting file appears after the run.</code></pre></article></section><section class="panel" id="verification"><h2 id="verdict">Waiting</h2><ul id="checks"></ul><p>Independent host checks stay separate from the SDK outcome. A read-only success or a turn limit should leave the failing exercise visibly unrepaired.</p></section><aside class="note">Normal completion, a limit, a refused/failed request and a transport failure are different outcomes. A budget is an SDK estimate threshold, not an exact billing guarantee. Session IDs are shown for observation; this sample disables transcript persistence and does not implement resume. Its local guards are not an operating-system sandbox.</aside>'+actions(('/learn.html','What you will learn →'),('/run.html','Configure and run →'))
document('/','Open the <em>agent loop.</em>','Observe real turns, messages, tool requests, feedback and final outcomes from the Lesson 04 presentation.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','Understand the <em>execution loop.</em>','The SDK runs the loop while your async iterator observes messages and outcomes.',cards(learn)+'<section class="step"><h2>Three real experiments</h2><ul><li><strong>Repair:</strong> run the failing tests, inspect code, edit auth.ts and run the tests again.</li><li><strong>One-turn limit:</strong> force maxTurns: 1 and preserve error_max_turns rather than reporting transport failure.</li><li><strong>Read-only inspection:</strong> remove Bash/Edit, inspect two files, and observe any shared response IDs or actual tool overlap.</li></ul><p>The presentation’s four-turn trace is illustrative. This app never manufactures four turns or assumes every message is a turn. The final SDK num_turns and observed response groups are displayed separately.</p></section><section class="step"><h2>Tools and concurrency</h2><p>Built-in tools include Read/Edit/Write, Glob/Grep, Bash, web tools and orchestration tools. This app enables only those needed for the chosen local task. Read-only requests may overlap when the model requests them together; mutation scheduling is owned by the runtime. This lesson provides no custom MCP tool. The slides’ readOnlyHint annotation is a custom-tool extension exercise, not a feature silently implemented here.</p><p>The iterator returns observable events; your handler can update a UI or cancel a run. It does not manually drive the next model/tool cycle. Assistant text is not hidden chain-of-thought.</p></section>'+actions(('/','← Loop explorer'),('/run.html','Setup and experiments →')))
run='<section class="step"><span class="number">01</span><h2>Install and configure the application</h2><p>Use Node.js 24+ and npm. Git for Windows/Git Bash may be required on Windows. Keep optional dependencies enabled for the SDK’s runtime. This lesson uses TypeScript and Node tests; Python is not needed.</p>'+snippet(clone,'powershell')+'<p>In the original presentations workspace, use <code>cd .\\agent-sdk\\lesson04-agent-loop</code> instead of cloning. Create a local configuration file without overwriting an existing one:</p>'+snippet('if (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env','powershell')+snippet(env,'dotenv')+'<p>If needed on Windows, set <code>CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe</code>. The SDK does not load .env itself; the web and sample:env commands load it explicitly. A key set in the shell takes precedence. Keep real keys out of source.</p></section>'
run+='<section class="step"><span class="number">02</span><h2>Run a normal repair</h2>'+snippet('npm start\n# Open http://127.0.0.1:3104','powershell')+'<p>Keep the terminal open. Choose Repair auth.ts, keep low effort and partial messages on, then click Run agent loop. The initial file has three failing cases and one passing case. Watch system/init, assistant tool requests, user feedback and a final result. A valid repair changes auth.ts and passes 4/4 independent checks.</p></section>'
run+='<section class="step"><span class="number">03</span><h2>Hit the turn limit deliberately</h2><p>After the normal run finishes, choose Hit maxTurns: 1. The preset enforces 1 on the server too. Run again and inspect the actual final subtype, cost, usage and stop reason. The task starts with npm test, so the limit experiment has insufficient room for the full repair cycle. Do not count a partial event, content block or hook as a separate turn. Tool order remains an actual model decision.</p></section>'
run+='<section class="step"><span class="number">04</span><h2>Inspect read-only execution and compare effort</h2><p>Choose Read-only inspection. Its prompt requests two file reads, and its tools exclude edits and shell commands. Observe request/result IDs and response group numbers. If hooks interleave, report the overlap you actually observed; do not assume two requests always run concurrently.</p><p>Repeat the same task with low and high effort to compare outcomes and estimated cost. Keep other controls fixed for a meaningful comparison. This app offers two supported effort levels for the configured model, rather than claiming every model supports every level from the slides.</p></section>'
run+='<section class="step"><span class="number">05</span><h2>Explore partial messages, budget and project settings</h2><p>Partial messages are requested with includePartialMessages. The trace hides those rows by default but counts them; use Show partial events to reveal them. Disabling the request produces no partial-message requirement. Lower maxBudgetUsd to observe an actual budget outcome; the response crossing the estimate threshold can still incur cost. Load project settings opts into settingSources: ["project"] and the bundled classroom CLAUDE.md. It is off by default. Session IDs do not imply persistence or a working resume UI.</p></section>'
run+='<section class="step"><span class="number">06</span><h2>Run and test from the terminal</h2><p>Same-shell authentication:</p>'+snippet(shell,'powershell')+'<p>For explicit file loading, use:</p>'+snippet('npm run sample:env -- repair low\nnpm run sample:env -- limit low\nnpm run sample:env -- inspect high\n\nnpm test\nnpm run build:client\npython scripts/build-pages.py','powershell')+'<p>Python is optional only for regenerating the teaching pages; it is not used by the app or its regression checks. Each model run can incur API usage. Starting the server does not call the API. Stop it with Ctrl+C. A duplicate app start prints its URL; another port listener requires stopping that service or changing PORT. Restart after configuration edits.</p></section>'
document('/run.html','Configure and <em>observe.</em>','Follow the normal, limited and read-only experiments with real SDK evidence.',run+actions(('/learn.html','← Learning goals'),('/','Open the loop explorer →')))
lanes=['Student','Host observer','Agent SDK','Claude API','Demo tools']
arrows=[(0,1,'1. Choose scenario and loop limits'),(1,4,'2. Reset auth.ts and test fixtures'),(1,2,'3. query(prompt, options)'),(2,1,'4. Yield system/init and partial events'),(2,3,'5. Send prompt and tool definitions'),(3,2,'6. Request one or more tools'),(2,4,'7. Apply hooks and run permitted tools'),(4,2,'8. Return execution feedback'),(2,1,'9. Yield user/tool_result with matching ID'),(2,3,'10. Send feedback; repeat if needed'),(2,1,'11. Yield typed final result and metadata'),(1,4,'12. Independently check actual auth.ts'),(1,0,'13. Show trace, outcome and evidence')]
details=['The selected controls become validated SDK options, not a simulated scenario playback.','The host restores a reproducible demo, including immutable test and package files.','One query object owns the whole model/tool loop.','The host observes lifecycle and optional partial events without treating each as a turn.','The runtime sends the task with available tool definitions to Claude.','The model chooses actual calls. Multiple content blocks may share a response ID.','Hooks observe and guard the calls. Only auth.ts edits and exactly npm test are permitted in repair mode.','Tools return results to the SDK. A failing npm test is useful feedback, not automatically a failed overall run.','tool_result.tool_use_id links back to the assistant tool_use.id.','The SDK performs the next model interaction itself; the host does not implement a manual Messages API loop.','The stream yields success or an error subtype with cost/usage/session metadata. Iterate through any trailing events.','Trusted host checks verify the resulting file even after a limit or read-only success.','Students compare final SDK status, response grouping, tool IDs, actual changes and independent checks.']
xs=[160,490,820,1150,1480];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1640" height="1620" viewBox="0 0 1640 1620"><title>Lesson 04 agent loop sequence</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1640" height="1620" fill="white"/><text x="40" y="52" font-size="32" font-family="Arial" font-weight="bold" fill="#101a44">One query · real messages, tools, feedback and results</text>']
for i,(x,label) in enumerate(zip(xs,lanes)):
 colour=['#087fff','#8838ff','#8838ff','#00a977','#087fff'][i];svg.append(f'<rect x="{x-145}" y="90" width="290" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" font-weight="bold" fill="white">{escape(label)}</text><path d="M{x} 170 V1570" stroke="#aec6df" stroke-dasharray="8 7"/>')
